from batch07 import *
start('ethernet','Ethernet, MAC i ARP','1.13',['https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst2960/software/release/15-2_2_e/configuration/guide/b_1522e_2960_2960c_2960s_2960sf_2960p_cg/b_1522e_2960_2960c_2960s_2960sf_2960p_cg_chapter_011.html','https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst3750x_3560x/software/release/15-0_2_se/configuration/guide/3750x_cg/swiprout.html'])
q('Nauka MAC','Z którego pola odebranej ramki switch uczy się adresu w dynamicznej tablicy MAC?','Ze źródłowego MAC',['Z docelowego MAC|Docelowy MAC służy do wyboru drogi przekazania.','Z docelowego IP|To nie pole używane do nauki MAC w zwykłym L2.','Z numeru TCP|Port TCP nie identyfikuje gniazda switcha.'],'Switch wiąże źródłowy MAC z portem wejściowym i VLAN-em.')
q('Decyzja L2','Którego adresu switch L2 szuka w tablicy, wybierając port wyjściowy dla unicast?','Docelowego MAC',['Źródłowego MAC|Służy do nauki, nie wskazuje odbiorcy ramki.','Źródłowego portu UDP|To informacja transportowa.','Adresu DNS switcha|Nie określa odbiorcy ramki.'],'Nauka źródła i wyszukanie celu są odrębnymi operacjami.')
c('Dynamiczna tabela','Pokaż dynamicznie nauczone adresy MAC na Catalyst IOS używając składni mac address-table.','SW# show mac address-table {{b0}}',['dynamic'],'Dynamiczna tabela odzwierciedla zaobserwowane źródła ramek.')
q('Unknown unicast','Docelowego MAC nie ma w tablicy VLAN 10. Co zwykle robi switch bez dodatkowych ograniczeń?','Rozsyła ramkę do pozostałych portów forwarding w VLAN 10',['Rozsyła ją zawsze do wszystkich VLAN-ów|Granica VLAN-u nadal obowiązuje.','Zamienia ją na zapytanie DNS|Switch L2 nie rozwiązuje celu przez DNS.','Zawsze odrzuca ramkę|Typowe zachowanie to flooding unknown unicast.'],'Flooding jest ograniczony VLAN-em, stanem portów i politykami; nie wraca na port wejściowy.')
c('Cache ARP routera','Pokaż cache ARP IPv4 na routerze IOS.','R1# show ip {{b0}}',['arp'],'ARP wiąże IP sąsiada na lokalnym łączu z jego adresem warstwy drugiej.')
q('ARP w lokalnym LAN','Do czego host używa ARP przed wysłaniem IPv4 do sąsiada w swoim Ethernet LAN?','Do ustalenia jego MAC',['Do uzyskania nazwy DNS|DNS rozwiązuje nazwy, nie ARP.','Do wybrania portu aplikacji|ARP nie negocjuje portów TCP/UDP.','Do zmiany maski podsieci|Maska jest konfigurowana innym mechanizmem.'],'ARP dotyczy lokalnego następnego kroku w IPv4, nie całej drogi do celu.')
q('Zdalny cel i lokalny MAC','PC wysyła pakiet do innej podsieci przez bramę. Jakiego MAC szuka przez ARP?','MAC bramy na swoim LAN-ie',['MAC zdalnego serwera za routerami|Host nie wysyła Ethernet bezpośrednio przez wszystkie routery.','MAC serwera DNS niezależnie od celu|DNS nie jest automatycznie next-hopem.','Zawsze ffff.ffff.ffff dla danych|Broadcast ARP nie oznacza broadcastu każdego pakietu danych.'],'Docelowe IP pozostaje zdalne, ale docelowy MAC pierwszej ramki należy do lokalnej bramy.')
q('Broadcast Ethernet','Który adres jest broadcastem Ethernet?','ffff.ffff.ffff',['0000.0000.0000|To nie standardowy adres broadcast.','192.168.1.255|To zapis IPv4, nie MAC.','01:00:5e:00:00:01|To adres multicast, nie broadcast Ethernet.'],'Broadcast Ethernet ma wszystkie 48 bitów ustawione na 1.')
c('MAC dla jednego VLAN-u','Wyświetl dynamiczne MAC wyłącznie w VLAN 25.','SW# show mac address-table {{b0}} vlan {{b1}}',['dynamic','25'],'Filtr VLAN pomaga rozdzielić obserwacje z różnych domen L2.')
q('Cel na porcie wejściowym','Ramka wchodzi G1/0/1. Tablica wskazuje jej docelowy MAC na tym samym porcie i VLAN-ie. Co zwykle robi switch?','Nie przekazuje jej z powrotem na ten sam port',['Zawsze flooduje po całym VLAN-ie|Cel jest znany, a nie unknown unicast.','Wysyła ją do innego VLAN-u|Nie ma podstaw do zmiany VLAN-u.','Zmienia docelowy MAC na własny|To nie zwykła operacja przełączania L2.'],'Odbiorca znajduje się po tej samej stronie; switch filtruje taką ramkę.')
c('Port i adresy','Pokaż status wszystkich portów, a następnie dynamiczne MAC na G1/0/7.','SW# show interfaces {{b0}}\nSW# show mac address-table dynamic interface {{b1}}',['status','GigabitEthernet1/0/7'],'Stan fizyczny i nauczone źródła to dwa różne dowody działania łącza.')
q('Wiek wpisu MAC','Dlaczego dynamiczny wpis MAC może zniknąć mimo braku zmiany kabla?','Przez wygaśnięcie czasu aging bez odświeżenia ruchem źródłowym',['MAC musi zmieniać się co minutę|Nie ma takiego ogólnego wymagania.','Każdy wpis DNS usuwa MAC|DNS nie steruje w ten sposób tablicą przełączania.','Wygaśnięcie zawsze dowodzi awarii switcha|Aging jest normalnym mechanizmem.'],'Wpis odświeża obserwacja źródła; brak wpisu sam nie dowodzi fizycznego odłączenia.')
q('MAC flapping','Ten sam MAC szybko pojawia się na dwóch różnych portach tego samego VLAN-u. Co warto zbadać?','Pętlę L2, duplikację MAC lub przemieszczanie urządzenia',['Wyłącznie długość dzierżawy DNS|DNS nie jest tu bezpośrednim wyjaśnieniem.','Tylko prefiks IPv6|Zjawisko dotyczy nauki adresu L2.','Uznać każdy taki przypadek za pewny atak|Istnieją również przyczyny topologiczne i operacyjne.'],'Flapping jest objawem wymagającym korelacji z topologią, STP i zdarzeniami.')
q('FCS','Jaką rolę pełni FCS w ramce Ethernet?','Wykrywa błędy transmisji przy użyciu sumy kontrolnej',['Szyfruje zawartość ramki|Kontrola integralności transmisji nie jest szyfrowaniem.','Potwierdza tożsamość użytkownika|FCS nie jest uwierzytelnianiem.','Wybiera bramę domyślną|Nie uczestniczy w wyborze trasy IP.'],'Poprawny FCS nie dowodzi autentyczności nadawcy ani poprawności danych aplikacji.')
c('Trzy widoki diagnostyczne','Na Catalyst sprawdź status portów, dynamiczne MAC VLAN 30 i tabelę ARP IPv4 switcha.','SW# show interfaces {{b0}}\nSW# show mac address-table {{b1}} vlan 30\nSW# show ip {{b2}}',['status','dynamic','arp'],'ARP switcha dotyczy jego funkcji IP; nie musi zawierać wszystkich hostów widocznych w MAC table.')
q('ARP nie jest MAC table','Switch ma MAC klienta w tablicy, ale nie ma jego IP w swoim ARP. Czy to sprzeczność?','Nie, te tablice uczą się na różne potrzeby',['Tak, każdy MAC wymaga wpisu ARP switcha|Przełączanie L2 może działać bez komunikacji IP switcha z hostem.','Tak, ARP zawsze jest kopią MAC table|ARP zawiera powiązania IP–MAC, nie sam MAC–port.','Nie, ponieważ ARP dotyczy wyłącznie IPv6|IPv6 używa ND, nie ARP.'],'Przełączanie ramek nie wymaga, aby sam switch rozwiązał IP każdego klienta.')
c('Porównaj sąsiednie porty','Pokaż dynamiczne MAC na G1/0/1 i G1/0/2, a następnie STP VLAN 10, aby zbadać ruch między portami.','SW# show mac address-table dynamic interface {{b0}}\nSW# show mac address-table dynamic interface {{b1}}\nSW# show spanning-tree vlan {{b2}}',['GigabitEthernet1/0/1','GigabitEthernet1/0/2','10'],'Łączna obserwacja MAC i STP pomaga odróżnić naukę źródeł od blokowania ścieżki.')
q('Ethernet przez router','Router przekazuje IPv4 z jednego Ethernet LAN-u do drugiego bez NAT. Co zwykle zmienia w enkapsulacji?','Tworzy nową ramkę Ethernet z MAC odpowiednimi dla następnego łącza',['Zachowuje end-to-end wszystkie MAC pierwszej ramki|Adresy L2 są właściwe dla konkretnego łącza.','Zawsze zmienia źródłowe IP na swoje|Bez NAT nie jest to zwykła zasada routingu.','Usuwa wszystkie nagłówki IP|Pakiet IP nadal jest potrzebny do przekazania.'],'Adresy IP i adresy warstwy drugiej mają inny zasięg; router zmienia także TTL IPv4.')
end()
start('transport','TCP i UDP — sesje i diagnostyka','1.5',['https://www.cisco.com/en/US/docs/ios-xml/ios/ipapp/configuration/15-1sy/iap-tcp.html','https://www.cisco.com/c/en/us/td/docs/switches/lan/catalyst3750x_3560x/software/release/15-0_2_se/configuration/guide/3750x_cg/swiprout.html'])
q('TCP a UDP','Który protokół zapewnia aplikacji uporządkowany strumień bajtów z retransmisjami?','TCP',['UDP|UDP sam nie zapewnia kolejności ani retransmisji.','ARP|ARP rozwiązuje adresy lokalnej warstwy drugiej.','ICMP|ICMP przenosi komunikaty kontrolne, nie taki strumień.'],'TCP realizuje niezawodny transport, o ile połączenie może działać; nie gwarantuje działania aplikacji.')
q('Handshake TCP','Jaka jest typowa kolejność ustanawiania TCP?','SYN → SYN/ACK → ACK',['ACK → FIN → SYN|FIN służy zamykaniu kierunku połączenia.','SYN → UDP → ACK|Handshake nie przechodzi na UDP.','FIN → RST → ACK|To nie standardowy proces ustanawiania.'],'Handshake uzgadnia numery sekwencji i potwierdza dwukierunkową komunikację TCP.')
q('Brak handshake UDP','Czy UDP musi wykonać transportowy handshake przed wysłaniem pierwszego datagramu?','Nie',['Tak, identyczny jak TCP|UDP nie definiuje takiego handshake.','Tak, musi wymienić SYN/ACK|Flagi te należą do TCP.','Tak, musi uzyskać sesję OSPF|Routing i transport to inne funkcje.'],'Aplikacja nad UDP może mieć własny handshake, ale nie wynika on z samego UDP.')
q('Numer portu','Co pozwalają rozróżniać porty TCP/UDP?','Punkty komunikacji aplikacji na hostach',['Fizyczne gniazda switcha|Port transportowy nie jest numerem gniazda Ethernet.','Wyłącznie VLAN-y|VLAN to segmentacja warstwy drugiej.','Długość maski podsieci|Maska nie jest portem transportowym.'],'Adres IP wskazuje host/interfejs, a port transportowy pomaga wskazać usługę lub proces.')
q('Kierunek odpowiedzi TCP','Klient 10.0.0.5:50000 łączy się do 192.0.2.10:443. Jakie porty ma typowa odpowiedź serwera?','Źródłowy 443, docelowy 50000',['Źródłowy 50000, docelowy 443|To kierunek klient do serwera.','Źródłowy 443, docelowy 443|Klient użył portu 50000.','Źródłowy 53, docelowy 50000|53 nie jest portem podanej sesji.'],'W kierunku powrotnym role adresów i portów są odwrócone.')
q('UDP i niezawodna aplikacja','Czy aplikacja nad UDP może samodzielnie implementować potwierdzenia i ponowienia?','Tak',['Nie, UDP zabrania potwierdzeń aplikacji|UDP nie narzuca takiego ograniczenia.','Tylko po zmianie IPv4 na IPv6|Wersja IP nie jest tym warunkiem.','Nie, bo każdy datagram musi zginąć|UDP nie gwarantuje strat ani ich braku.'],'Brak niezawodności w UDP nie wyklucza implementacji tych mechanizmów wyżej.')
q('ACK kolejnego bajtu','TCP otrzymał 100 bajtów zaczynając od sekwencji 1000, bez luk i bez SYN/FIN. Jaki kolejny numer potwierdza?','1100',['1099|To numer ostatniego odebranego bajtu, nie następnego oczekiwanego.','1001|To odpowiadałoby jednemu bajtowi przestrzeni sekwencji.','2000|Nie wynika z podanej długości segmentu.'],'ACK zwykle wskazuje następny oczekiwany numer sekwencji: 1000 + 100.')
q('SYN zajmuje numer','Klient wysyła SYN z SEQ=700 bez danych. Jakiego ACK oczekuje w SYN/ACK?','701',['700|SYN zajmuje jedno miejsce w przestrzeni sekwencji.','702|Bez danych SYN zużywa jedno, nie dwa miejsca.','0|ACK nie zeruje automatycznie przestrzeni sekwencji.'],'Flaga SYN jest potwierdzana przez dodanie jednego do jej numeru sekwencji.')
q('Odbiorca i okno','Czemu służy advertised receive window TCP?','Informuje o przestrzeni, którą odbiorca może przyjąć',['Wskazuje tylko szybkość fizycznego portu|Okno nie jest stałą przepustowością Ethernet.','Wybiera numer VLAN-u|Nie dotyczy segmentacji L2.','Gwarantuje brak przeciążenia całej ścieżki|Flow control odbiorcy nie zastępuje congestion control.'],'Flow control chroni odbiorcę; przeciążenie sieci jest osobnym problemem.')
q('MSS a MTU','Co określa TCP MSS?','Maksymalny rozmiar danych TCP w segmencie, deklarowany przez stronę',['Cały rozmiar ramki Ethernet wraz z FCS|To nie wielkość MSS.','Wyłącznie rozmiar nagłówka IP|MSS dotyczy danych TCP.','Liczbę wszystkich sesji routera|To nie limit liczby połączeń.'],'MSS nie obejmuje nagłówków IP/TCP i nie jest tym samym co MTU.')
q('FIN kontra RST','Która flaga TCP jest kojarzona z nagłym przerwaniem/resetem połączenia?','RST',['FIN|FIN oznacza uporządkowane zakończenie nadawania w danym kierunku.','SYN|SYN służy synchronizacji przy ustanawianiu.','ACK|ACK potwierdza dane i sam nie oznacza resetu.'],'RST należy interpretować wraz z kierunkiem i kontekstem: może go wysłać host lub urządzenie pośrednie.')
q('ACK nie potwierdza aplikacji','Serwer potwierdził bajty TCP. Czy to dowodzi zapisania transakcji w bazie danych?','Nie',['Tak, ACK jest potwierdzeniem SQL commit|TCP nie zna semantyki transakcji aplikacji.','Tak, jeśli port to 443|Port nie zmienia zakresu potwierdzenia TCP.','Tak, każdy ACK zawiera odpowiedź aplikacji|ACK może nie mieć danych aplikacyjnych.'],'Potwierdzenie transportowe nie zastępuje odpowiedzi ani potwierdzenia operacji aplikacyjnej.')
q('Ping działa, HTTPS nie','Host odpowiada na ping, ale sesja TCP 443 nie powstaje. Co z tego wynika?','ICMP działa, lecz trzeba osobno zbadać TCP i usługę',['Cała aplikacja HTTPS na pewno działa|Ping nie sprawdza TCP ani TLS.','DNS na pewno jest uszkodzony|Test IP może w ogóle nie korzystać z DNS.','Sieć musi odrzucać wszystkie pakiety|ICMP właśnie przeszedł.'],'Dostępność jednego protokołu nie dowodzi dostępności innego.')
q('Powtarzający się SYN','Widać powtarzane SYN klienta, brak SYN/ACK i RST. Co jest poprawnym wnioskiem?','Nie ma obserwowanej odpowiedzi; przyczyną może być filtr, droga powrotna lub host',['Na pewno błędne hasło aplikacji|Uwierzytelnienie aplikacji jeszcze nie nastąpiło.','Na pewno poprawna cała ścieżka|Brak odpowiedzi tego nie potwierdza.','Na pewno jeden konkretny firewall|Sama obserwacja nie lokalizuje winnego urządzenia.'],'Przechwycenia w kolejnych punktach i kontrola obu kierunków pomagają zawęzić problem.')
q('Retransmisja a utrata','Czy retransmisja TCP widoczna w jednym miejscu bezwarunkowo dowodzi utraty danych na konkretnym łączu?','Nie',['Tak, wskazuje zawsze najbliższy switch|Miejsce obserwacji nie lokalizuje automatycznie straty.','Tak, zawsze oznacza uszkodzony kabel|Przyczyny obejmują także opóźnienie, reorganizację i utratę ACK.','Nie, TCP nigdy nie retransmituje|Retransmisja jest mechanizmem TCP.'],'Należy zbadać dane, ACK, czas i kompletność przechwycenia przed wskazaniem przyczyny.')
q('Okno zero','Odbiorca ogłasza TCP window=0. Co to zwykle oznacza?','Aktualnie nie ma dostępnego miejsca na dalsze dane w oknie odbiorczym',['Natychmiast usunięto trasę IP|Okno nie jest tablicą routingu.','Port Ethernet zmienił się w shutdown|Stan okna nie oznacza tego automatycznie.','Połączenie musi zostać natychmiast zamknięte|TCP może monitorować ponowne otwarcie okna.'],'Zero window kieruje uwagę na odbiorcę i przetwarzanie danych, nie tylko na ścieżkę sieciową.')
q('MSS przy IPv4','Dla MTU 1500, nagłówka IPv4 20 B i TCP 20 B bez opcji, jaki rozmiar danych mieści się w jednym pakiecie?','1460 B',['1500 B|Trzeba odjąć oba nagłówki.','1480 B|Odjęto tylko jeden z dwóch nagłówków.','1440 B|Nie wynika z podanych rozmiarów nagłówków.'],'1500 − 20 − 20 = 1460; dodatkowa enkapsulacja może zmienić dostępny rozmiar.')
q('Dwie sesje HTTPS','Ten sam klient ma dwie jednoczesne sesje do tego samego IP serwera na TCP 443. Co może je odróżniać?','Różny port źródłowy klienta',['Tylko inny fizyczny kabel|Sesje mogą korzystać z tego samego kabla.','Każda wymaga innego docelowego VLAN-u|Nie jest to warunek dwóch sesji.','Serwer musi zmienić adres MAC dla każdej sesji|MAC nie identyfikuje sesji TCP.'],'Połączenie TCP rozróżnia para adresów IP i portów, w kontekście protokołu transportowego.')
end()
